// H7 Set A, job 2: record updates -- plain Node. Generated by gen_jobs.py.
const N_RECORDS = 2000;
const N_BUMPS = 50;

const records = [];
for (let i = 1; i <= N_RECORDS; i++) records.push({ id: i, value: 0 });
const bumps = [];
for (let b = 1; b <= N_BUMPS; b++) bumps.push(b);

let total = 0;
for (const r of records) {
  for (const b of bumps) r.value += b;
  total += r.value;
}

console.log(`total ${total}`);
